#include <iostream>
#include <vector>
#include <string>

int main() {
  std::vector<std::string> strings = {"hello", "world"};
  //auto iterator = strings.begin(); // iterator type is deduced
  for (const auto& str : strings) { //Using auto and reference for efficiency
    std::cout << str << " ";
  }
  std::cout << std::endl;
  auto sum = 10 + 20.5; // sum is double
  std::cout << "Sum: " << sum << std::endl;
  decltype(strings.begin()) iter = strings.begin(); //iter has the same type as strings.begin()
  std::cout << *iter << std::endl;
  return 0;
}
